// dp[mask][i] = min cost to visit set 'mask', ending at city i
vector<vector<int>> dp(1<<n, vector<int>(n, INF));
dp[1][0] = 0;                                   // start at city 0
for (int mask = 1; mask < (1<<n); ++mask)
  for (int i = 0; i < n; ++i) if (dp[mask][i] < INF)
    for (int j = 0; j < n; ++j) if (!(mask & (1<<j)))
      dp[mask | (1<<j)][j] = min(dp[mask | (1<<j)][j], dp[mask][i] + cost[i][j]);

def tsp(cost):
    n = len(cost)
    INF = float('inf')
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0                                # start at city 0
    for mask in range(1, 1 << n):
        for i in range(n):
            if dp[mask][i] == INF:
                continue
            for j in range(n):
                if not (mask & (1 << j)):
                    nm = mask | (1 << j)
                    dp[nm][j] = min(dp[nm][j], dp[mask][i] + cost[i][j])
    full = (1 << n) - 1
    return min(dp[full][i] + cost[i][0] for i in range(n))
